results=[]
def check(name,fn):
    try:
        value=fn()
        if value is False: raise AssertionError('Assertion returned false')
        results.append({'name':name,'pass':True})
    except Exception as e:results.append({'name':name,'pass':False,'error':str(e)})
    (ART/'browser-summary.json').write_text(json.dumps(results,indent=2))
